def triple_barrier_label(price_path, pt=0.02, sl=0.01, max_bars=10):
    entry = price_path[0]
    for i, p in enumerate(price_path[1:max_bars+1], 1):
        ret = p / entry - 1
        if ret >= pt:
            return 1    # profit-take touched first
        if ret <= -sl:
            return -1   # stop-loss touched first
    final_ret = price_path[max_bars] / entry - 1
    return 1 if final_ret > 0 else -1  # time barrier
